CREATE COLUMN TABLE "TEST_AP"."OCNT" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(7) NOT NULL , "Country" NVARCHAR(3) NOT NULL , "State" NVARCHAR(3) NOT NULL , "Name" NVARCHAR(100), "TaxZone" NVARCHAR(1) DEFAULT 'N', "IbgeCode" NVARCHAR(10), "GiaCode" NVARCHAR(10), PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCNT_UNIQUE" ON "TEST_AP"."OCNT" ( "Code" ASC, "Country" ASC, "State" ASC )